#include <iostream>
#include <string>
using namespace std;
extern Node* prob2(Battle* battles, int n);
extern void prob4(Node*& head, string general);
int main(){
    Battle b1; b1.name="B1"; b1.from_date="01-01-2000"; b1.total_famous_generals=1; b1.list_famous_generals=new string[1]; b1.list_famous_generals[0]="Napoleon";
    Battle b2; b2.name="B2"; b2.from_date="01-01-2001"; b2.total_famous_generals=1; b2.list_famous_generals=new string[1]; b2.list_famous_generals[0]="Julius";
    Battle b3; b3.name="B3"; b3.from_date="01-01-2002"; b3.total_famous_generals=2; b3.list_famous_generals=new string[2]; b3.list_famous_generals[0]="Napoleon"; b3.list_famous_generals[1]="Julius";
    Battle* arr = new Battle[3]; arr[0]=b1; arr[1]=b2; arr[2]=b3;
    Node* head = prob2(arr,3);
    prob4(head, "Napoleon");
    for(Node* cur=head; cur; cur=cur->next) cout << cur->battle.name << "\n";
    return 0;
}

